public class Main{
    public static void main(String[] args){
        Scanner s=new Scanner(System.in);if(!s.hasNextInt())return;
        int n=s.nextInt();
        int m=Integer.MAX_VALUE, mx=0;
        for(int i=0;i<n;i++){
            int x=s.nextInt();
            if(x<m) m=x; else if(x-m>mx) mx=x-m;
        }
        System.out.println(mx);
    }
}

