struct Node {
    int key, val;
    Node *prev, *next;
    Node(int k=0, int v=0): key(k), val(v), prev(nullptr), next(nullptr) {}
};

class LRUCache {
    int cap;
    unordered_map<int, Node*> cache;
    Node* head;
    Node* tail;
    void remove(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }
    void insert(Node* node) {
        node->prev = head;
        node->next = head->next;
        head->next->prev = node;
        head->next = node;
    }
public:
    LRUCache(int capacity) {
        cap = capacity;
        head = new Node();
        tail = new Node();
        head->next = tail;
        tail->prev = head;
    }
    int get(int key) {
        if (cache.count(key)) {
            remove(cache[key]);
            insert(cache[key]);
            return cache[key]->val;
        }
        return -1;
    }
    void put(int key, int value) {
        if (cache.count(key)) {
            remove(cache[key]);
            cache[key]->val = value;
            insert(cache[key]);
            return;
        }
        if (cache.size() == cap) {
            Node* lru = tail->prev;
            cache.erase(lru->key);
            remove(lru);
            delete lru;
        }
        Node* node = new Node(key, value);
        cache[key] = node;
        insert(node);
    }
