#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int key, val;
    struct Node *prev, *next;
} Node;

typedef struct {
    int cap, size;
    Node* head;
    Node* tail;
    Node** map;
} LRUCache;

LRUCache* lRUCacheCreate(int capacity) {
    LRUCache* cache = (LRUCache*)malloc(sizeof(LRUCache));
    cache->cap = capacity;
    cache->size = 0;
    cache->head = (Node*)malloc(sizeof(Node));
    cache->tail = (Node*)malloc(sizeof(Node));
    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;
    cache->map = (Node**)calloc(10001, sizeof(Node*));
    return cache;
}

void removeNode(Node* node) {
    node->prev->next = node->next;
    node->next->prev = node->prev;
}

void insertNode(LRUCache* cache, Node* node) {
    node->prev = cache->head;
    node->next = cache->head->next;
    cache->head->next->prev = node;
    cache->head->next = node;
}

int lRUCacheGet(LRUCache* obj, int key) {
    if (obj->map[key]) {
        removeNode(obj->map[key]);
        insertNode(obj, obj->map[key]);
        return obj->map[key]->val;
    }
    return -1;
}

void lRUCachePut(LRUCache* obj, int key, int value) {
    if (obj->map[key]) {
        removeNode(obj->map[key]);
        obj->map[key]->val = value;
        insertNode(obj, obj->map[key]);
        return;
    }
    if (obj->size == obj->cap) {
        Node* lru = obj->tail->prev;
        obj->map[lru->key] = NULL;
        removeNode(lru);
        free(lru);
        obj->size--;
    }
    Node* node = (Node*)malloc(sizeof(Node));
    node->key = key; node->val = value;
    obj->map[key] = node;
    insertNode(obj, node);
    obj->size++;
}

void lRUCacheFree(LRUCache* obj) {
    Node* curr = obj->head;
    while (curr) {
        Node* next = curr->next;
        free(curr);
        curr = next;
    }
    free(obj->map);
    free(obj);
}

int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    LRUCache* obj = NULL;
    for (int i = 0; i < n; ++i) {
        char cmd[20];
