        if (strcmp(cmd, "LRUCache") == 0) {
            int capacity; scanf("%d", &capacity);
            obj = lRUCacheCreate(capacity);
            printf("null\n");
        } else if (strcmp(cmd, "get") == 0) {
            int k; scanf("%d", &k);
            printf("%d\n", lRUCacheGet(obj, k));
        } else if (strcmp(cmd, "put") == 0) {
            int k, v; scanf("%d %d", &k, &v);
            lRUCachePut(obj, k, v);
            printf("null\n");
        }
    }
    return 0;
}

