#define MIN_VAL(a, b) ((a) < (b) ? (a) : (b))

typedef struct {
    char** history;
    int curr;
    int size;
    int capacity;
} BrowserHistory;

BrowserHistory* browserHistoryCreate(char * homepage) {
    BrowserHistory* obj = (BrowserHistory*)malloc(sizeof(BrowserHistory));
    obj->capacity = 5005;
    obj->history = (char**)malloc(obj->capacity * sizeof(char*));
    obj->history[0] = strdup(homepage);
    obj->curr = 0;
    obj->size = 1;
    return obj;
}
void browserHistoryVisit(BrowserHistory* obj, char * url) {
    for (int i = obj->curr + 1; i < obj->size; i++) free(obj->history[i]);
    obj->curr++;
    obj->history[obj->curr] = strdup(url);
    obj->size = obj->curr + 1;
}
char * browserHistoryBack(BrowserHistory* obj, int steps) {
    obj->curr = MAX_VAL(0, obj->curr - steps);
    return obj->history[obj->curr];
}
