#include <iostream>
#include <string>
#include <vector>
using namespace std;

vector<string> fullJustify(vector<string>& words, int maxWidth) {
    vector<string> res;
    int n = words.size();
    for(int i = 0; i < n; ) {
        int j = i + 1, lineLen = words[i].length();
        while(j < n && lineLen + 1 + words[j].length() <= maxWidth) {
            lineLen += 1 + words[j].length();
            j++;
        }
        string line = words[i];
        int spaces = maxWidth - lineLen + (j - i - 1);
        if (j == n || j - i == 1) {
            for(int k = i + 1; k < j; k++) line += " " + words[k];
            line += string(maxWidth - line.length(), ' ');
        } else {
            int spacesPerWord = spaces / (j - i - 1);
            int extraSpaces = spaces % (j - i - 1);
            for(int k = i + 1; k < j; k++) {
                line += string(spacesPerWord + (k - i <= extraSpaces ? 1 : 0), ' ') + words[k];
            }
        }
        res.push_back(line);
        i = j;
    }
    return res;
}

int main() {
