import java.util.*;

class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        for(int i = 0; i < words.length; ) {
            int j = i + 1, lineLen = words[i].length();
            while(j < words.length && lineLen + 1 + words[j].length() <= maxWidth) {
                lineLen += 1 + words[j].length();
                j++;
            }
            StringBuilder sb = new StringBuilder(words[i]);
            int spaces = maxWidth - lineLen + (j - i - 1);
            if (j == words.length || j - i == 1) {
                for(int k = i + 1; k < j; k++) sb.append(" ").append(words[k]);
                while(sb.length() < maxWidth) sb.append(" ");
            } else {
                int spacesPerWord = spaces / (j - i - 1);
                int extraSpaces = spaces % (j - i - 1);
                for(int k = i + 1; k < j; k++) {
                    int s = spacesPerWord + (k - i <= extraSpaces ? 1 : 0);
                    for(int m = 0; m < s; m++) sb.append(" ");
                    sb.append(words[k]);
                }
            }
            res.add(sb.toString());
            i = j;
        }
        return res;
    }
}

